import json, re, os, time, urllib.request, urllib.error
from datetime import datetime, timezone
import sys
live = open("live.txt", "a", buffering=1)
def say(s):
    sys.stdout.write(str(s) + "\n")
    sys.stdout.flush()
    live.write(str(s) + "\n")
say("MONITOR_START %s" % datetime.now(timezone.utc).isoformat()[:19])
raw = os.environ["BLAND_API_KEY"].strip()
if raw.startswith("{"):
    p = json.loads(raw); raw = next((p[k] for k in ("api_key", "key", "value") if p.get(k)), raw)
gw = os.environ["GW_TOKEN"].strip()
if not gw.lower().startswith("bearer"):
    gw = "Bearer " + gw
PILOT = {
    "0bf471cf-cba5-47e6-9382-9dd43325eb28": "6220",
    "2c4f5747-445a-40e3-b675-cfdcafe62c7f": "9019",
    "bdaccf66-3b59-4732-b044-6a5185d26542": "7407",
    "48d4c9c0-3b66-4afa-9459-34f33da11ae0": "2116",
    "8a124841-e9d4-4e7c-8594-7599c79b6b05": "0935",
    "b8b4add0-5ef6-4887-9e35-59a028aa96c9": "4949",
    "8db9378d-2ca9-4e9e-83af-01c221999286": "3046",
    "8b6e0f29-bc35-41ce-bdcb-344510c861ac": "4078",
    "d0c514dc-31d9-461f-b5f6-f02cfcf245b3": "4618",
    "b5920ad5-21f2-455c-b1f5-4be6959fb938": "3625",
}
say("PILOT_LOADED n=%d" % len(PILOT))
END = datetime.now(timezone.utc).replace(hour=23, minute=59, second=0)
BANNED = re.compile(r"one moment|let me check|checking availability|please hold|give me a (?:moment|second)", re.I)

def bland(path):
    req = urllib.request.Request("https://api.bland.ai" + path, headers={"Authorization": raw, "User-Agent": "mybcat-cli"})
    with urllib.request.urlopen(req, timeout=90) as r:
        return json.loads(r.read().decode())

def gwcall(path, payload):
    req = urllib.request.Request("https://mott-booking-gw.mail.mybcat.com" + path, data=json.dumps(payload).encode(), method="POST", headers={"Content-Type": "application/json", "Authorization": gw, "User-Agent": "mybcat-cli"})
    try:
        with urllib.request.urlopen(req, timeout=90) as r:
            return r.status, json.loads(r.read().decode() or "{}")
    except urllib.error.HTTPError as e:
        return e.code, str(e.read())[:120]

state = {}
booked_seen = set()
cycle = 0
while datetime.now(timezone.utc) < END:
    cycle += 1
    active = replied = booked = stopped = 0
    for cid, tail in PILOT.items():
        try:
            det = bland("/v1/sms/conversations/%s" % cid)
            d = det.get("data") if isinstance(det.get("data"), dict) else det
        except Exception as e:
            say("WARN detail ...%s: %s" % (cid[-6:], str(e)[:80]))
            continue
        msgs = d.get("messages") or []
        node = str(d.get("current_node_id"))
        active += 1
        prev = state.get(cid, {"msgs": 1, "node": "n_goal_ask"})
        user_n = sum(1 for m in msgs if isinstance(m, dict) and m.get("sender") != "AGENT")
        if user_n:
            replied += 1
        if len(msgs) != prev["msgs"] or node != prev["node"]:
            last = msgs[-1] if msgs else {}
            say("EVENT conv=...%s cell=***%s node=%s msgs=%d last_from=%s" % (cid[-6:], tail, node, len(msgs), (last.get("sender", "?") if isinstance(last, dict) else "?")))
        for m in msgs:
            if isinstance(m, dict) and m.get("sender") == "AGENT" and BANNED.search(str(m.get("message", ""))):
                say("ALERT FILLER conv=...%s" % cid[-6:])
        fails = [m for m in msgs if isinstance(m, dict) and str(m.get("status", "")).lower() in ("failed", "undelivered")]
        if fails:
            say("ALERT DELIVERY_FAIL conv=...%s n=%d" % (cid[-6:], len(fails)))
        if node in ("n_suppress_stop", "n_suppress_not_me", "e_stop", "e_not_me", "e_declined", "e_timeout"):
            stopped += 1
            if prev["node"] != node:
                say("ALERT OPTOUT conv=...%s node=%s" % (cid[-6:], node))
        if node in ("n_post_booking", "e_booked", "e_booked_recovered"):
            booked += 1
            if cid not in booked_seen:
                booked_seen.add(cid)
                pid = re.sub(r"\D", "", str((d.get("variables") or {}).get("recall_patient_id", "")))
                if pid:
                    s, b = gwcall("/appt-list", {"patient_id": pid, "store": "711"})
                    ap = ((b.get("result") or {}).get("appointments") or []) if isinstance(b, dict) else []
                    say("BOOKED conv=...%s pid=***%s gw_count=%d starts=%s" % (cid[-6:], pid[-4:], len(ap), [a.get("start") for a in ap]))
                else:
                    say("BOOKED conv=...%s pid=UNKNOWN (no recall_patient_id in variables)" % cid[-6:])
        state[cid] = {"msgs": len(msgs), "node": node}
    say("CYCLE %d %s active=%d replied=%d booked=%d stopped=%d" % (cycle, datetime.now(timezone.utc).strftime("%H:%M"), active, replied, booked, stopped))
    time.sleep(120)
say("MONITOR_END cycles=%d" % cycle)
PY
